参考实现（JavaScript）：
function unique(arr) {
  return [...new Set(arr)];
}
// 等价的手写哈希版：
// function unique(arr) {
//   const seen = new Set(), out = [];
//   for (const x of arr) if (!seen.has(x)) { seen.add(x); out.push(x); }
//   return out;
// }
时间复杂度 O(n)（哈希集合的增删查为均摊 O(1)），额外空间 O(n)。

参考实现（JavaScript）：
function firstUniqChar(s) {
  const cnt = {};
  for (const ch of s) cnt[ch] = (cnt[ch] || 0) + 1;
  for (let i = 0; i < s.length; i++) {
    if (cnt[s[i]] === 1) return i;
  }
  return -1;
}
时间复杂度 O(n)：第一遍统计各字符出现次数，第二遍按顺序找第一个计数为 1 的字符（哈希表均摊 O(1)），空间 O(k)（k 为字符集大小）。

参考实现（JavaScript）：
function deepClone(v) {
  if (v === null || typeof v !== 'object') return v;
  if (Array.isArray(v)) return v.map(deepClone);
  const out = {};
  for (const k of Object.keys(v)) out[k] = deepClone(v[k]);
  return out;
}
说明：1）循环引用会导致无限递归（栈溢出），需用 WeakMap 记录「已拷贝对象 → 副本」再遇到时直接复用；2）Date、RegExp、Map、Set、TypedArray 等特殊对象按普通对象处理会失真，需分支特判；3）函数通常按引用复制（或按需省略）；4）Symbol 键、不可枚举属性、原型链未被复制（如需完整语义可用 structuredClone 或库实现）。
